"use client";
import {
    ChangeEvent,
    FC,
    FormEvent,
    useState,
    useRef,
    useCallback,
    useEffect,
} from "react";
import type Message from "../types/Message";

interface Props {
    handleMessage: (message: string) => boolean;
    isGenerating: boolean;
}

const MessageInput: FC<Props> = ({ handleMessage, isGenerating }) => {
    const [inputMessage, setInputMessage] = useState("");
    const [height, setScrollHeight] = useState<string | number>("auto");
    const textareaRef = useRef(null);
    const isShift = useRef(false);

    const submit = useCallback(() => {
        const reset = handleMessage(inputMessage);
        if (reset) setInputMessage("");
    }, [inputMessage, handleMessage]);

    const handleChange = (e: ChangeEvent<HTMLTextAreaElement>) => {
        setInputMessage(e.target.value);
        setScrollHeight(e.target.scrollHeight);
    };

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        submit();
    };

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Enter" && !isShift.current) {
                e.preventDefault();
                if (!isGenerating) submit();
            } else if (e.key === "Shift") {
                isShift.current = true;
            }
        };

        const handleKeyUp = (e: KeyboardEvent) => {
            if (e.key === "Shift") {
                isShift.current = false;
            }
        };

        window.addEventListener("keydown", handleKeyDown);
        window.addEventListener("keyup", handleKeyUp);

        return () => {
            window.removeEventListener("keydown", handleKeyDown);
            window.removeEventListener("keyup", handleKeyUp);
        };
    }, [inputMessage, submit, isGenerating]);

    return (
        <form className="flex w-full gap-5 p-5" onSubmit={handleSubmit}>
            <textarea
                className="grow ring-none outline-none border-none rounded ring-2 ring-gray-200 focus:ring-2 focus:ring-blue-500 p-5 dark:bg-slate-800 dark:ring-gray-600"
                value={inputMessage}
                // onChange={(e) => setInputMessage(e.target.value)}
                onChange={handleChange}
                placeholder="Your Message"
                autoFocus
                style={{ height: `${height}px` }}
                ref={textareaRef}
            />
            <button
                className={`bg-blue-500 text-white rounded-md p-2 px-6 font-semibold ${
                    isGenerating ? "cursor-not-allowed" : ""
                }`}
                type="submit"
            >
                {isGenerating ? (
                    <div className="w-7 h-7 animate-spin bg-transparent border-4 rounded-full border-t-transparent"></div>
                ) : (
                    "send"
                )}
            </button>
        </form>
    );
};

const socket = new WebSocket("ws://localhost:4000");

interface ServerMessage {
    type: "incoming_token" | "start_message" | "end_message";
    token?: string;
}

interface ClientMessage {
    type: "message";
    content?: string;
}

export function ChatWindow() {
    const [messages, setMessages] = useState<Message[]>([
        { role: "assistant", content: "how can i help you today" },
    ]);

    const [isGenerating, setIsGenerating] = useState(false);
    const [incomingMessage, setIncomingMessage] = useState("");

    useEffect(() => {
        console.log("bro");
        socket.addEventListener("open", () => {
            console.log("connected to socket");
        });
    }, []);

    useEffect(() => {
        if (isGenerating === false && incomingMessage !== "") {
            setMessages([
                ...messages,
                { content: incomingMessage, role: "assistant" },
            ]);
            setIncomingMessage("");
        }
    }, [isGenerating, incomingMessage, messages]);

    useEffect(() => {
        const pageHeight = document.body.scrollHeight;
        window.scroll({
            behavior: "smooth",
            left: 0,
            top: pageHeight,
        });
    }, [incomingMessage]);

    useEffect(() => {
        function handleIncomingMessage(e: MessageEvent) {
            const message: ServerMessage = JSON.parse(e.data);

            if (message.type === "start_message") {
                setIsGenerating(true);
                setIncomingMessage("");
            } else if (message.type === "end_message") {
                console.log(incomingMessage);
                setIsGenerating(false);
            } else {
                setIncomingMessage(`${incomingMessage}${message.token}`);
            }
        }

        socket.addEventListener("message", handleIncomingMessage);

        return () => {
            socket.removeEventListener("message", handleIncomingMessage);
        };
    }, [messages, incomingMessage, isGenerating]);

    return (
        <div className="flex flex-col min-h-screen">
            <div className="w-full flex flex-col justify-center min-h-screen">
                <div className="w-full flex justify-center flex-grow">
                    <div className="w-full max-w-5xl">
                        <Messages
                            messages={
                                isGenerating
                                    ? [
                                          ...messages,
                                          {
                                              role: "assistant",
                                              content: incomingMessage,
                                          },
                                      ]
                                    : messages
                            }
                        />
                    </div>
                </div>

                <div className="sticky bottom-0 w-full flex justify-center">
                    <div className="w-full max-w-5xl">
                        <MessageInput
                            isGenerating={isGenerating}
                            handleMessage={(m) => {
                                if (isGenerating || m === "") return false;

                                const clientMessage: ClientMessage = {
                                    type: "message",
                                    content: m,
                                };
                                socket.send(JSON.stringify(clientMessage));

                                setMessages([
                                    ...messages,
                                    { role: "user", content: m },
                                ]);

                                return true;
                            }}
                        />
                    </div>
                </div>
            </div>
        </div>
    );
}

interface MessagesProps {
    messages: Message[];
}

const Messages: FC<MessagesProps> = ({ messages }) => {
    return (
        <ul className="px-5">
            {messages.map((m, i) => (
                <li
                    className={`p-5 flex flex-col gap-3 rounded ${
                        m.role === "user"
                            ? ""
                            : "bg-slate-100 dark:bg-slate-800"
                    }`}
                    key={i}
                >
                    <p className="font-bold">
                        {m.role === "user" ? "you:" : "assistant:"}
                    </p>
                    {m.content
                        .trim()
                        .split("```")
                        .map((chunk, chunkI) =>
                            chunkI % 2 == 1 ? (
                                <pre
                                    className="bg-gray-950 p-3 rounded text-white overflow-x-scroll"
                                    key={`chunk: ${chunkI}`}
                                >
                                    {chunk.trim()}
                                </pre>
                            ) : (
                                chunk
                                    .split("\n")
                                    .map((t, i) =>
                                        t !== "" ? <p key={i}>{t}</p> : ""
                                    )
                            )
                        )}
                </li>
            ))}
        </ul>
    );
};
